import { DEFAULT_SETTINGS, MODEL } from './shared/constants.js';
import { getModelState } from './shared/storage.js';

const OFFSCREEN_DOCUMENT = 'offscreen.html';
const tabStats = new Map();
let creatingOffscreen = null;

async function ensureOffscreen() {
  if (await chrome.offscreen.hasDocument()) return;
  if (!creatingOffscreen) {
    creatingOffscreen = chrome.offscreen.createDocument({
      url: OFFSCREEN_DOCUMENT,
      reasons: [chrome.offscreen.Reason.BLOBS],
      justification: 'Decode images and run private ONNX inference outside webpage contexts.'
    }).finally(() => {
      creatingOffscreen = null;
    });
  }
  await creatingOffscreen;
}

async function prewarmInstalledModel() {
  await ensureOffscreen();
  const response = await chrome.runtime.sendMessage({ target: 'offscreen', type: 'PRELOAD_MODEL' });
  if (!response?.ok) {
    const error = new Error(response?.error || 'Model preload failed.');
    error.code = response?.errorCode || 'MODEL_PRELOAD_FAILED';
    throw error;
  }
}

chrome.runtime.onInstalled.addListener(async ({ reason }) => {
  const current = await chrome.storage.local.get(DEFAULT_SETTINGS);
  await chrome.storage.local.set({ ...DEFAULT_SETTINGS, ...current });
  if (reason === 'install') await chrome.runtime.openOptionsPage();
  prewarmInstalledModel().catch((error) => console.warn('[Local Lens] Preload failed.', safeError(error)));
});

chrome.runtime.onStartup.addListener(() => {
  prewarmInstalledModel().catch((error) => console.warn('[Local Lens] Preload failed.', safeError(error)));
});

chrome.tabs.onRemoved.addListener((tabId) => tabStats.delete(tabId));
chrome.tabs.onUpdated.addListener((tabId, changeInfo) => {
  if (changeInfo.status === 'loading') {
    tabStats.delete(tabId);
    chrome.action.setBadgeText({ tabId, text: '' }).catch(() => {});
  }
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.target !== 'background') return false;
  handleMessage(message, sender)
    .then(sendResponse)
    .catch((error) => sendResponse({
      ok: false,
      error: safeError(error),
      errorCode: error?.code || 'BACKGROUND_ERROR'
    }));
  return true;
});

async function handleMessage(message, sender) {
  switch (message.type) {
    case 'ENSURE_OFFSCREEN':
      await ensureOffscreen();
      return { ok: true };

    case 'OPEN_SETUP':
      await chrome.runtime.openOptionsPage();
      return { ok: true };

    case 'GET_STATUS': {
      const state = await getModelState();
      const currentModelReady = Boolean(
        state.modelInstalled && state.modelState?.id === MODEL.id
      );
      return {
        ok: true,
        ...state,
        modelInstalled: currentModelReady,
        modelState: currentModelReady ? state.modelState : null,
        stats: tabStats.get(message.tabId) ?? { analyzed: 0, flagged: 0, failed: 0 }
      };
    }

    case 'GET_OFFSCREEN_MODEL_RECORD': {
      assertOffscreenSender(sender);
      const record = await chrome.storage.local.get({
        modelInstalled: false,
        modelState: null,
        lastInstallError: null
      });
      return { ok: true, record };
    }

    case 'SET_OFFSCREEN_MODEL_RECORD': {
      assertOffscreenSender(sender);
      const values = sanitizeModelRecord(message.values);
      await chrome.storage.local.set(values);
      return { ok: true };
    }

    case 'ANALYZE_IMAGE': {
      let state = await getModelState();
      let modelInstalled = Boolean(
        state.modelInstalled && state.modelState?.id === MODEL.id
      );
      if (!modelInstalled) {
        await prewarmInstalledModel();
        state = await getModelState();
        modelInstalled = Boolean(
          state.modelInstalled && state.modelState?.id === MODEL.id
        );
      }
      if (!modelInstalled) {
        return { ok: false, errorCode: 'NOT_INSTALLED', error: 'The bundled detector could not be activated.' };
      }
      await ensureOffscreen();
      const result = await chrome.runtime.sendMessage({
        target: 'offscreen',
        type: 'ANALYZE_IMAGE',
        payload: message.payload
      });
      if (sender.tab?.id != null) updateStats(sender.tab.id, result);
      return result;
    }

    default:
      return { ok: false, errorCode: 'UNKNOWN_MESSAGE', error: 'Unknown request.' };
  }
}

function updateStats(tabId, result) {
  const stats = tabStats.get(tabId) ?? { analyzed: 0, flagged: 0, failed: 0 };
  if (result?.ok) {
    stats.analyzed += 1;
    if (result.result?.isAI) stats.flagged += 1;
  } else {
    stats.failed += 1;
  }
  tabStats.set(tabId, stats);
  chrome.action.setBadgeBackgroundColor({ tabId, color: '#ef5b3f' }).catch(() => {});
  chrome.action.setBadgeText({ tabId, text: stats.flagged ? String(stats.flagged) : '' }).catch(() => {});
}

function assertOffscreenSender(sender) {
  if (sender.id !== chrome.runtime.id || sender.url !== chrome.runtime.getURL(OFFSCREEN_DOCUMENT)) {
    const error = new Error('Privileged model-state access is restricted to the offscreen extension page.');
    error.code = 'UNAUTHORIZED_STORAGE_REQUEST';
    throw error;
  }
}

function sanitizeModelRecord(values) {
  const source = values && typeof values === 'object' ? values : {};
  const output = {};
  if (Object.hasOwn(source, 'modelInstalled')) output.modelInstalled = Boolean(source.modelInstalled);
  if (Object.hasOwn(source, 'modelState')) output.modelState = source.modelState ?? null;
  if (Object.hasOwn(source, 'lastInstallError')) output.lastInstallError = source.lastInstallError ?? null;
  if (!Object.keys(output).length) {
    const error = new Error('No recognized model-state fields were supplied.');
    error.code = 'INVALID_STORAGE_REQUEST';
    throw error;
  }
  return output;
}

function safeError(error) {
  return error instanceof Error ? error.message : String(error);
}
