import { DEFAULT_SETTINGS } from './constants.js';

export async function getSettings() {
  const values = await chrome.storage.local.get(DEFAULT_SETTINGS);
  return {
    enabled: Boolean(values.enabled),
    threshold: Number(values.threshold) || DEFAULT_SETTINGS.threshold,
    minDimension: Number(values.minDimension) || DEFAULT_SETTINGS.minDimension,
    maxImagesPerPage: Number(values.maxImagesPerPage) || DEFAULT_SETTINGS.maxImagesPerPage
  };
}

export async function getModelState() {
  const value = await chrome.storage.local.get({
    modelInstalled: false,
    modelState: null
  });
  return value;
}
